1	import { and, eq, inArray, isNull, ne, or } from "drizzle-orm";
2	import type { Db } from "@paperclipai/db";
3	import { agents, issues } from "@paperclipai/db";
4	import type { Request } from "express";
5	import { forbidden } from "../errors.js";
6	import { assertCompanyAccess } from "./authz.js";
7	
8	const WORKSPACE_RUNTIME_ELIGIBLE_ISSUE_STATUSES: string[] = [
9	  "backlog",
10	  "todo",
11	  "in_progress",
12	  "in_review",
13	  "blocked",
14	];
