16	async function listReportingSubtreeAgentIds(db: Db, companyId: string, actorAgentId: string) {
17	  const companyAgents = await db
18	    .select({
19	      id: agents.id,
20	      reportsTo: agents.reportsTo,
21	    })
22	    .from(agents)
23	    .where(and(eq(agents.companyId, companyId), ne(agents.status, "terminated")));
24	
25	  const reportsByManager = new Map<string, string[]>();
26	  for (const agent of companyAgents) {
27	    if (!agent.reportsTo) continue;
28	    const reports = reportsByManager.get(agent.reportsTo) ?? [];
29	    reports.push(agent.id);
30	    reportsByManager.set(agent.reportsTo, reports);
31	  }
32	
33	  const visited = new Set<string>([actorAgentId]);
34	  const queue = [actorAgentId];
35	  while (queue.length > 0) {
36	    const current = queue.shift();
37	    if (!current) continue;
38	    const reports = reportsByManager.get(current) ?? [];
39	    for (const reportId of reports) {
40	      if (visited.has(reportId)) continue;
41	      visited.add(reportId);
42	      queue.push(reportId);
43	    }
44	  }
45	
46	  return [...visited];
47	}
