49	async function assertAgentCanManageRuntimeServicesForWorkspace(
50	  db: Db,
51	  req: Request,
52	  input: {
53	    companyId: string;
54	    projectWorkspaceId?: string | null;
55	    executionWorkspaceId?: string | null;
56	    sourceIssueId?: string | null;
57	  },
58	) {
59	  if (req.actor.type !== "agent" || !req.actor.agentId) {
60	    throw forbidden("Agent authentication required");
61	  }
62	
63	  const actorAgent = await db
64	    .select({
65	      id: agents.id,
66	      companyId: agents.companyId,
67	      role: agents.role,
68	    })
69	    .from(agents)
70	    .where(eq(agents.id, req.actor.agentId))
71	    .then((rows) => rows[0] ?? null);
72	
73	  if (!actorAgent || actorAgent.companyId !== input.companyId) {
74	    throw forbidden("Agent key cannot access another company");
75	  }
76	
77	  if (actorAgent.role === "ceo") {
78	    return;
79	  }
80	
81	  const eligibleAgentIds = await listReportingSubtreeAgentIds(db, input.companyId, actorAgent.id);
82	  const workspaceScopeConditions = [
83	    input.projectWorkspaceId ? eq(issues.projectWorkspaceId, input.projectWorkspaceId) : null,
84	    input.executionWorkspaceId ? eq(issues.executionWorkspaceId, input.executionWorkspaceId) : null,
85	    input.sourceIssueId ? eq(issues.id, input.sourceIssueId) : null,
86	  ].filter((condition): condition is NonNullable<typeof condition> => condition !== null);
87	
88	  if (workspaceScopeConditions.length === 0) {
89	    throw forbidden("Missing permission to manage workspace runtime services");
90	  }
91	
92	  const linkedIssue = await db
93	    .select({ id: issues.id })
94	    .from(issues)
95	    .where(and(
96	      eq(issues.companyId, input.companyId),
97	      isNull(issues.hiddenAt),
98	      inArray(issues.status, WORKSPACE_RUNTIME_ELIGIBLE_ISSUE_STATUSES),
99	      inArray(issues.assigneeAgentId, eligibleAgentIds),
100	      workspaceScopeConditions.length === 1
101	        ? workspaceScopeConditions[0]!
102	        : or(...workspaceScopeConditions),
103	    ))
104	    .then((rows) => rows[0] ?? null);
105	
106	  if (linkedIssue) {
107	    return;
108	  }
109	
110	  throw forbidden("Missing permission to manage workspace runtime services");
111	}
