113	export async function assertCanManageProjectWorkspaceRuntimeServices(
114	  db: Db,
115	  req: Request,
116	  input: {
117	    companyId: string;
118	    projectWorkspaceId: string;
119	  },
120	) {
121	  assertCompanyAccess(req, input.companyId);
122	  if (req.actor.type === "board") return;
123	  await assertAgentCanManageRuntimeServicesForWorkspace(db, req, input);
124	}
